/** AVL tree with insertion rotations and invariant checking. */
class TeachingAVL { static class N { int k,h; N l,r; N(int k){this.k=k;} } N root; int h(N n){return n==null?-1:n.h;} int bf(N n){return n==null?0:h(n.l)-h(n.r);} void upd(N n){n.h=1+Math.max(h(n.l),h(n.r));} N rr(N y){N x=y.l; y.l=x.r; x.r=y; upd(y); upd(x); return x;} N rl(N x){N y=x.r; x.r=y.l; y.l=x; upd(x); upd(y); return y;} void insert(int k){root=ins(root,k);} N ins(N n,int k){if(n==null)return new N(k); if(k<n.k)n.l=ins(n.l,k); else if(k>n.k)n.r=ins(n.r,k); upd(n); if(bf(n)>1&&k<n.l.k)return rr(n); if(bf(n)<-1&&k>n.r.k)return rl(n); if(bf(n)>1){n.l=rl(n.l);return rr(n);} if(bf(n)<-1){n.r=rr(n.r);return rl(n);} return n;} boolean ok(){return ok(root);} boolean ok(N n){return n==null || Math.abs(bf(n))<=1 && ok(n.l)&&ok(n.r);} }
